        setValue(L.DESC_COMMAND_REVALIDATE_PARAM, "Work out the hash of all the summaries again so none becomes outdated; true when omitted");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY, "Searches the parts of the story (and their summaries) of the open book and, after you confirm, replaces the matches. Options after the replacement, in this order: regex (false), case sensitive (true), search in summaries (true), search in all branches (false), revalidate all summaries (true).");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY_LLM, "Search and replace in the story text of the book: the parts of the story and optionally their summaries, in the active branch or in all of them. Changes the book, and the change can't be undone; the user is asked to confirm the number of matches first, an agent is covered by its destructive mode. Count first: with dryRun true nothing is changed and the answer says how many matches there are and shows a few; with maxHits a replace that finds more matches than that is refused. Asynchronous. Optional values, positional and in this order: regex, caseSensitive, summaries, allBranches, revalidateSummaries, maxHits, dryRun.");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY_RETURN, "What was done: how many matches in how many parts were replaced, or that nothing was found or the user did not confirm");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_LOREBOOK, "Searches the entries (name, text and comment) of the lorebook of the open book and, after you confirm, replaces the matches. Options after the replacement, in this order: regex (false), case sensitive (true).");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_LOREBOOK_LLM, "Search and replace in the lorebook of the book: the name, text and comment of the entries of the root lorebook. Changes the book, and the change can't be undone; the user is asked to confirm the number of matches first, an agent is covered by its destructive mode. Count first: with dryRun true nothing is changed and the answer says how many matches there are and shows a few; with maxHits a replace that finds more matches than that is refused. Asynchronous. Optional values, positional and in this order: regex, caseSensitive, maxHits, dryRun.");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_LOREBOOK_RETURN, "What was done: how many matches in how many entries were replaced, or that nothing was found or the user did not confirm");
        setValue(L.DESC_COMMAND_PART_PARAM, "The part: its handle (the \"handle\" of the lists), or its position on the branch, the first part of the story is 1. Prefer the handle, positions move when parts are added or deleted");
        setValue(L.DESC_COMMAND_BRANCH_PARAM, "The branch: the handle of a part on it, or its number from list-branches; the active branch when omitted");
